CREATE FUNCTION [dbo].[Q_GARDESH_KHFR_MAND_SUB](@Forms___F_MENU_KOL_MOIN_TAFZIL___DT1 [bigint], @Forms___F_MENU_KOL_MOIN_TAFZIL___HTTAF [nvarchar](40)) RETURNS TABLE AS RETURN (SELECT     dbo.DEED_HED.DATE_S, dbo.CUST_HESAB.hes AS HES, dbo.CUST_HESAB.NAME, dbo.DEED_DTL.BED, dbo.DEED_DTL.BES, dbo.DEED_DTL.id,                      dbo.DEED_DTL.N_S FROM         dbo.DEED_HED INNER JOIN                      dbo.DEED_DTL ON dbo.DEED_HED.N_S = dbo.DEED_DTL.N_S INNER JOIN                      dbo.CUST_HESAB ON dbo.DEED_DTL.HES = dbo.CUST_HESAB.hes  WHERE ((dbo.DEED_HED.DATE_S < @Forms___F_MENU_KOL_MOIN_TAFZIL___DT1) AND (dbo.DEED_DTL.RADIF IS NULL) and  (dbo.DEED_DTL.hes = @Forms___F_MENU_KOL_MOIN_TAFZIL___HTTAF)) OR   ((dbo.DEED_HED.DATE_S < @Forms___F_MENU_KOL_MOIN_TAFZIL___DT1) AND (dbo.DEED_HED.NO_S = 0) and  (dbo.DEED_DTL.hes = @Forms___F_MENU_KOL_MOIN_TAFZIL___HTTAF))  UNION  SELECT     dbo.UDATEADD(dbo.HEAD_LST.DATE_N, dbo.HEAD_LST.MAS) AS SDATE, dbo.HEAD_LST.CUST_NO, dbo.CUST_HESAB.NAME, (dbo.INVO_LST.MEGHk - dbo.INVO_LST.MEGH_MAR) * dbo.INVO_LST.MABL AS bed, 0 AS bes, dbo.INVO_LST.RADIF, dbo.HEAD_LST.NUMBER FROM         dbo.CUST_HESAB INNER JOIN                       dbo.HEAD_LST ON dbo.CUST_HESAB.hes = dbo.HEAD_LST.CUST_NO INNER JOIN                      dbo.STUF_DEF INNER JOIN                      dbo.INVO_LST ON dbo.STUF_DEF.CODE = dbo.INVO_LST.CODE ON dbo.HEAD_LST.TAG = dbo.INVO_LST.TAG AND                      dbo.HEAD_LST.NUMBER = dbo.INVO_LST.NUMBER WHERE     (dbo.HEAD_LST.DATE_N < @Forms___F_MENU_KOL_MOIN_TAFZIL___DT1) AND (dbo.HEAD_LST.TAG = 2) AND                     (dbo.HEAD_LST.CUST_NO = @Forms___F_MENU_KOL_MOIN_TAFZIL___HTTAF)   UNION SELECT     dbo.UDATEADD(dbo.HEAD_LST.DATE_N, dbo.HEAD_LST.MAS) AS SDATE, dbo.HEAD_LST.CUST_NO, dbo.CUST_HESAB.NAME, 0 AS bed,                      (dbo.INVO_LST.MEGHk - dbo.INVO_LST.MEGH_MAR) * dbo.INVO_LST.MABL AS bes, dbo.INVO_LST.RADIF, dbo.HEAD_LST.NUMBER  FROM         dbo.CUST_HESAB INNER JOIN                      dbo.HEAD_LST INNER JOIN                      dbo.STUF_DEF INNER JOIN                      dbo.INVO_LST ON dbo.STUF_DEF.CODE = dbo.INVO_LST.CODE ON dbo.HEAD_LST.TAG = dbo.INVO_LST.TAG AND                      dbo.HEAD_LST.NUMBER = dbo.INVO_LST.NUMBER ON dbo.CUST_HESAB.hes = dbo.HEAD_LST.CUST_NO WHERE     (dbo.HEAD_LST.DATE_N < @Forms___F_MENU_KOL_MOIN_TAFZIL___DT1) AND (dbo.HEAD_LST.TAG = 1) AND                      (dbo.HEAD_LST.CUST_NO = @Forms___F_MENU_KOL_MOIN_TAFZIL___HTTAF))
